// Agrega contas vencendo POR DONO
const contasAll = items.filter(i => i.json && i.json.id && i.json.janela);
if (!contasAll.length) return [];

function money(v, sym){ if (v == null) return ''; const n = Number(v); return isNaN(n) ? '' : ' ' + sym + ' ' + n.toFixed(2).replace('.', ','); }

const porDono = {};
for (const c of contasAll) { (porDono[c.json.dono_numero] ||= []).push(c.json); }

const out = [];
const sqls = [];
for (const [dono, contas] of Object.entries(porDono)) {
  const SYM = (contas[0].moeda === 'USD') ? '$' : 'R$';
  const atrasadas = contas.filter(c => c.janela === 'atrasada');
  const hoje = contas.filter(c => c.janela === 'hoje');
  const amanha = contas.filter(c => c.janela === 'amanha');
  const prox = contas.filter(c => c.janela === 'proximos_3d');

  let partes = [];
  if (atrasadas.length) partes.push('*ATRASADAS:*\n' + atrasadas.slice(0,5).map(c => `  #${c.id} ${c.descricao}${money(c.valor, SYM)} (venceu ${c.venc})`).join('\n') + (atrasadas.length > 5 ? `\n  ...e mais ${atrasadas.length-5}` : ''));
  if (hoje.length) partes.push('*Vencem HOJE:*\n' + hoje.map(c => `  #${c.id} ${c.descricao}${money(c.valor, SYM)}`).join('\n'));
  if (amanha.length) partes.push('*Vencem amanha:*\n' + amanha.map(c => `  #${c.id} ${c.descricao}${money(c.valor, SYM)}`).join('\n'));
  if (prox.length) partes.push('*Proximos 3 dias:*\n' + prox.slice(0,5).map(c => `  #${c.id} ${c.descricao}${money(c.valor, SYM)} (${c.venc})`).join('\n') + (prox.length > 5 ? `\n  ...e mais ${prox.length-5}` : ''));
  if (!partes.length) continue;

  const total = contas.reduce((s,c) => s + Number(c.valor || 0), 0);
  let texto = 'Contas a pagar:\n\n' + partes.join('\n\n');
  if (total > 0) texto += `\n\nTotal: ${SYM} ${total.toFixed(2).replace('.', ',')}`;
  texto += '\n\nQuando pagar, manda o comprovante ou fala "paguei a #ID" que eu dou baixa.';

  const idsHoje = hoje.map(c => c.id);
  const idsAmanha = amanha.map(c => c.id);
  const idsProx = prox.map(c => c.id);
  if (idsHoje.length) sqls.push(`UPDATE giulia_contas_pagar SET lembrete_dia_enviado = TRUE WHERE id IN (${idsHoje.join(',')});`);
  if (idsAmanha.length) sqls.push(`UPDATE giulia_contas_pagar SET lembrete_1d_enviado = TRUE WHERE id IN (${idsAmanha.join(',')});`);
  if (idsProx.length) sqls.push(`UPDATE giulia_contas_pagar SET lembrete_3d_enviado = TRUE WHERE id IN (${idsProx.join(',')});`);

  out.push({ json: { send_to: dono, send_text: texto } });
}
if (!out.length) return [];
const sqlFlags = sqls.join('\n') || 'SELECT 1;';
out.forEach(o => o.json.sql_flags = sqlFlags);
return out;
